const SPEED_STORAGE_KEY='tiny-army-battle-speed-v1';
function readBattleSpeed(){try{const value=storage?.getItem(SPEED_STORAGE_KEY);return ['1','2','3'].includes(value)?Number(value):1}catch(e){return 1}}
function saveBattleSpeed(){try{storage?.setItem(SPEED_STORAGE_KEY,String(speed))}catch(e){/* Keep the current session's choice when storage is unavailable. */}}
const campaign=new TinyArmyCampaign.Campaign({storage,autoLoad:true});
let game=null,view='camp',speed=readBattleSpeed(),paused=false,last=0,accumulator=0,uiElapsed=0,viewW=900,viewH=580,clock=0,visualScale=1,rewardBursts=[],skillBursts=[];
let conditionFeedback=null;
let rewardSelectionOwner=null,rewardSelectionVersion=0,selectedReplacementId=null,modalSequence=0;
let shopSelectionOwner=null,shopSelectionVersion=0,selectedShopId=null,selectedShopReplacementId=null;
let formationInput=null,battleFrame={zoom:1,offsetX:0,offsetY:0};
let modalState=null,focusBeforeModal=null,pauseBeforeModal=false,selectedUnitId=null,targeting=null,toastUntil=0,lastBattleId=null,selectedRewardId=null,rewardSelectionKey='',castInProgress=false,lastSceneKey='';
const motionQuery=(()=>{try{return globalThis.matchMedia?.('(prefers-reduced-motion: reduce)')}catch{return null}})(),combatCues=new Map(),reduceMotion=()=>globalThis.TinyArmyGraphics?.effective().reducedMotion??!!motionQuery?.matches;
const graphics=()=>globalThis.TinyArmyGraphics,visualSettings=()=>graphics()?.effective()||{renderScale:1,pixelRatioCap:2,particleAmount:1,decorativeBackground:true,glow:true,uiAnimation:true,reducedMotion:!!motionQuery?.matches};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Math.round(Number(n)||0).toLocaleString('ko-KR'),percent=n=>Math.round((Number(n)||0)*100)+'%';
const icon=(type,options={})=>globalThis.TinyArmyCardArt?.portrait(type,{size:96,condition:100,...options})||art?.portrait(type)||'',actionIcon=name=>art?.icons[name]||'';
const metricIcon=(id,size=20)=>`<span class="metric-icon" aria-hidden="true">${globalThis.TinyArmyCardArt?.metric(id,{size})||''}</span>`;
const signedMetric=(delta,unit='')=>Math.abs(Number(delta)||0)<1e-9?'변화 없음':`${delta>0?'+':'−'}${metric(Math.abs(delta))}${unit}`;
// Names depend only on persistent identity, never type, slot, RNG or roster order.
const UNIT_NAMES=['나루','보리','하루','여울','다온','마루','이솔','라온','해솔','누리','아라','도담','시온','소담','가온','루리'];
function unitName(u){const id=Math.max(0,Math.floor(Number(u.id)||1)-1),base=UNIT_NAMES[id%UNIT_NAMES.length];let group=Math.floor(id/UNIT_NAMES.length),prefix='';while(group){group--;prefix=String.fromCharCode(0xac00+group%11172)+prefix;group=Math.floor(group/11172)}return prefix+base}
const label=u=>`${unitName(u)} · ${TYPES[u.type]?.name||u.type}`;
const btn=(text,action,data='',cls='secondary',disabled=false)=>`<button class="${cls}" data-action="${action}" ${data} ${disabled?'disabled':''}>${text}</button>`;
const roles={mage:'후열 · 자동 주문',spear:'전열 · 근접',archer:'후열 · 원거리',support:'후열 · 치유',guardian:'근접 · 주변 아군 보호',charger:'근접 · 범위 타격',sniper:'원거리 · 강한 단발',volley:'원거리 · 다중 사격'};
const roleHeadlines={mage:'마나로 비전 화살을 자동 시전',guardian:'자신과 주변 아군을 지키는 전열',charger:'별도 주기로 범위 타격',sniper:'약한 적 조준 · 세 번째 공격 강화',volley:'서로 다른 적 최대 3명 동시 사격',support:'체력 비율이 낮은 아군 치유',spear:'앞에서 적을 막는 근접 병사',archer:'뒤에서 단일 적을 공격'};
function roleTrait(type){return {mage:'사거리 220 안의 적 한 명에게 비전 화살을 자동으로 사용해요. 마나 20을 소모하고 재사용은 6초예요. 대상이 없으면 마나를 소모하지 않아요. 주문은 치명타가 없으며 적의 방어·피해 감소가 적용돼요. 지휘 기술과 마나·재사용을 공유하지 않아요.',sniper:'매 3번째 기본공격은 1.9배 피해. 사거리 안에서 현재 HP가 가장 낮은 적을 우선 조준해요. 사거리 내 집중 공격 대상이 있으면 그 명령이 우선해요.',volley:'공격마다 사거리 안의 서로 다른 적 최대 3명에게 각각 기본공격 피해를 줘요. 가까운 적 우선이며, 사거리 내 집중 공격 대상은 첫 대상으로 선택해요.',guardian:'자신이 받는 피해를 28% 줄여요. 거리 155 미만의 방벽병이 아닌 아군은 20%p 추가 감소를 받아요. 여러 방벽병의 보호는 중첩되지 않으며 전체 피해 감소 상한은 55%예요.',charger:'가장 가까운 적이 거리 150 미만이면 그 위치에 반경 112의 범위 타격을 예고해요. 0.45초 후 공격력의 1.6배 피해, 재사용 9초(첫 준비 2초). 시전자가 쓰러지면 취소돼요. 집중 공격 명령과 별도이며 창병 기본공격 유물 보너스는 이 타격에 적용되지 않아요.',support:'치유 사거리 220 안에서 체력 비율이 가장 낮은 부상 아군을 치유해요. 치유 간격 2.8초(첫 준비 2초)이며 기본공격과 별도로 작동해요. 기본공격 가속은 치유를 가속하지 않아요. 치유 대상이 멀면 다가가고, 평소에는 아군 뒤를 따라가요.',spear:'가장 가까운 적에게 접근해 단일 대상 근접 기본공격을 해요. 사거리 안의 집중 공격 명령을 우선해요.',archer:'가장 가까운 적에게 원거리 기본공격을 해요. 사거리 안의 집중 공격 명령을 우선해요.'}[type]||''}

const skills={heal:{name:'회복',icon:'relic-field-medkit',copy:'살아 있는 아군을 회복'},guard:{name:'수호',icon:'relic-ironwall-seal',copy:'잠시 아군이 받는 피해 감소'},focus:{name:'집중 공격',icon:'relic-keen-spear-tip',copy:'적 한 명을 골라 집중 공격'},rally:{name:'사기 고양',icon:'relic-battle-drum',copy:'잠시 아군의 공격 속도 상승'}};
const nodeNames={battle:'일반전',normal:'일반전',elite:'정예전',boss:'장 보스',rest:'휴식',shop:'상점',event:'이벤트'};
const skillIcon=id=>globalThis.TinyArmyRelicArt?.icon(skills[id]?.icon,{size:48})||'';
const screenArt=()=>globalThis.TinyArmyScreenArt,motion=()=>globalThis.TinyArmyMotion;
const scene=kind=>`<div class="screen-scene" aria-hidden="true">${screenArt()?.backdrop(kind,{chapter:campaign.run.chapter})||''}</div>`;
const metric=n=>globalThis.TinyArmyStrategyView.format(n);
const paired=(before,after)=>{const p=globalThis.TinyArmyStrategyView.pair(before,after);return {...p,delta:p.deltaNumber===0?'변화 없음':p.delta}};
const skillName=id=>C.SKILLS?.[id]?.name||skills[id]?.name||id;
const relicDef=id=>Array.isArray(C.RELICS)?C.RELICS.find(r=>r.id===id):(C.RELICS?.[id]);
const relicName=id=>relicDef(id)?.name||id;
const rarityName=r=>globalThis.TinyArmyRarityArt?.tier(r)?.nameKo||r;
// Shared v05 art has a terminal rank-number group; remove that group only.
const relicIcon=r=>{const svg=rarityArt?.icon(relicDef(r.id)?.iconId||{'banner':'relic-marching-banner','seal':'relic-ironwall-seal','spear_tip':'relic-keen-spear-tip','medic':'relic-field-medkit','whistle':'relic-counter-whistle','drum':'relic-battle-drum'}[r.id],r.rarity||'common',{size:64,decorative:true})||'';return `<span class="relic-art-wrap">${svg.replace(/<g aria-hidden="true"><rect[^>]*\/><path[^>]*\/><\/g>(?=<\/svg>$)/,'')}<span class="relic-stack-badge">×${r.stacks||1}</span></span>`};
function liveRelicAction(offer){const preview=C.relicAction?.(campaign.run.relics,offer.relic);if(!preview)return{action:offer.action,existing:offer.existing,requiresReplacement:offer.requiresReplacement,result:offer.relic};const existing=campaign.run.relics.find(r=>r.id===offer.relic.id)||null;return {...preview,existing,result:preview.result||(preview.valid===false&&existing?existing:offer.relic)}}
const relicOutcome=offer=>offer.purchased?(campaign.run.relics.find(r=>r.id===offer.relic.id)||offer.relic):liveRelicAction(offer).result;
const relicDescription=r=>C.describeRelic?C.describeRelic(r.id,r.rarity,r.stacks||1):(relicDef(r.id)?.description||'');
const inactiveRelic=r=>r.id==='drum'&&!campaign.run.skills.includes('rally');
const nodeName=n=>n?.encounter?.name||(n?.type==='event'?campaign.eventDefinition?.(n)?.name:'')||(C.EVENTS||[]).find(e=>e.id===n?.eventId)?.name||n?.name||'';
const nodeDescription=n=>{const event=n?.type==='event'?campaign.eventDefinition?.(n):null;return n?.encounter?.description||(event?[event.description,event.chapterFlavor].filter(Boolean).join(' '):'')||(C.EVENTS||[]).find(e=>e.id===n?.eventId)?.description||n?.description||''};
const terminal=()=>['complete','defeat','retired'].includes(campaign.phase);
const chapterDef=()=>Array.isArray(C.CHAPTERS)?C.CHAPTERS.find(c=>c.id===campaign.run.chapter||c.chapter===campaign.run.chapter)||C.CHAPTERS[campaign.run.chapter-1]:C.CHAPTERS?.[campaign.run.chapter];
const nodeIcon=type=>type==='rest'?globalThis.TinyArmyRelicArt?.icon('relic-field-medkit',{size:48}):type==='shop'?globalThis.TinyArmyRelicArt?.icon('relic-counter-whistle',{size:48}):type==='event'?actionIcon('evolve'):type==='boss'?actionIcon('boss'):type==='elite'?icon('armored'):actionIcon('stage0');
const roster=()=>campaign.roster||campaign.run.roster||[];
function clearNotices(){for(const id of ['toast','modalNotice']){const notice=$(id);if(notice)notice.hidden=true}toastUntil=0}
function say(text){clearNotices();$('announcer').textContent=text;const notice=modalState?$('modalNotice')||$('toast'):$('toast');notice.textContent=text;notice.hidden=false;toastUntil=performance.now()+4000}
function mutation(method,...args){cancelFormationInput();const conditionBefore=['finishBattle','rest','event'].includes(method)?conditionStats():null;let result;try{result=campaign[method](...args)}catch(error){say('처리하지 못했어요. 진행 상태를 확인하고 다시 시도해 주세요.');console.error(error);return false}if(result===false||result===null){say(campaign.lastError||'지금은 이 행동을 할 수 없어요.');return false}if(conditionBefore){const after=conditionStats();conditionFeedback={before:conditionBefore.average,after:after.average,beforeMin:conditionBefore.minimum,afterMin:after.minimum,reason:method==='rest'?'휴식 후 컨디션':method==='event'?'선택 후 컨디션':'전투 후 컨디션',pending:true,scene:null,run:campaign.run,nodeId:campaign.run.currentNodeId}}updateSaveWarning();return result}
function updateSaveWarning(){const message=campaign.storageError||(!storage?'브라우저 저장을 사용할 수 없어요. 내보내기로 진행 상황을 보관해 주세요.':'');$('saveWarning').hidden=!message;$('saveWarning').textContent=message?`저장 안내 · ${message}`:''}
function chapterTitle(){return chapterDef()?.name||`${campaign.run.chapter}장`}
function updateHeader(){
 const legacy=campaign.run.combatRulesVersion==='v05-combat-1';if($('legacyRulesBanner')){$('legacyRulesBanner').hidden=!legacy;$('legacyRulesBanner').textContent=legacy?'이전 원정 이어하기 · 이번 원정은 기존 지도·전투·보상 규칙을 유지해요. 새 원정부터 v0.8 규칙이 적용돼요.':''}
 $('goldStat').textContent=number(campaign.run.gold);$('tokenStat').textContent=number(campaign.profile.tokens);
 const inCamp=view==='camp',node=campaign.currentNode;
 $('stageHeading').textContent=inCamp?'작은 군단의 야영지':view==='map'?`${campaign.run.chapter}장 · ${chapterTitle()}`:nodeName(node)||'원정 기록';
 $('stageDescription').textContent=inCamp?`군단 레벨 ${campaign.profile.level}`:view==='event'?nodeDescription(node):'';
 $('stageDescription').hidden=!$('stageDescription').textContent;
 if($('stageProgress'))$('stageProgress').textContent=inCamp?'':`${Math.max(0,campaign.run.row+1)}/9`;
 updateSaveWarning();
}
function render(){
 cancelFormationInput();
 if(view!=='camp')view=campaign.phase==='map'?'map':campaign.phase==='prepare'?'prepare':campaign.phase==='battle'?'battle':campaign.phase;
 const conditionElement=$('conditionTransition'),keepCondition=!!(conditionElement?.isConnected&&conditionFeedback&&!conditionFeedback.pending&&conditionFeedback.run===campaign.run&&conditionFeedback.nodeId===campaign.run.currentNodeId&&view!=='camp'&&view!=='battle');if(!keepCondition)globalThis.TinyArmyConditionTransition?.clear();
 $('appShell').dataset.view=view;const sceneKey=`${campaign.run.id}:${view}:${campaign.run.currentNodeId||''}`,sceneChanged=sceneKey!==lastSceneKey;if(sceneChanged){motion()?.newScene(sceneKey);lastSceneKey=sceneKey}updateHeader();const battle=view==='battle'&&!!game;
 $('screen').hidden=battle;$('battleScreen').hidden=!battle;
 if(battle){renderBattle();$('actionBar').innerHTML=btn('군단 · 유물','roster')+btn('전투 기록','result');resize();if(sceneChanged)motion()?.enter($('battleScreen'));return}
 const screens={camp:renderCamp,map:renderMap,prepare:renderPrepare,reward:renderReward,rest:renderRest,shop:renderShop,event:renderEvent,nodeComplete:renderNodeComplete,complete:renderSettlement,defeat:renderSettlement,retired:renderSettlement};
 const screen=screens[view]||renderCamp;screen();const transition=globalThis.TinyArmyConditionTransition;if(conditionFeedback?.pending||keepCondition)conditionFeedback.scene=sceneKey;else if(conditionFeedback?.scene!==sceneKey)conditionFeedback=null;if(conditionFeedback&&transition){if(keepCondition)$('screen').replaceChildren(conditionElement,...Array.from($('screen').childNodes||$('screen').children));else $('screen').innerHTML=`<div id="conditionTransition">${transition.markup(conditionFeedback)}</div>`+$('screen').innerHTML;if(conditionFeedback.pending){transition.play($('conditionTransition'),conditionFeedback);conditionFeedback.pending=false}}else transition?.clear();if(sceneChanged)motion()?.enter($('screen'));
 if(modalState)renderModal(false);else bindFormationInput();
}
function renderCamp(){
 const r=campaign.run,p=campaign.profile,started=r.visited.length>0,finished=terminal(),unlocks=campaign.unlockOptions?.()||[];
 $('screen').innerHTML=`${scene('camp')}<div class="camp-hero"><span class="eyebrow">OUR LITTLE EXPEDITION</span><h2>작은 발걸음, 새로운 길</h2><div class="camp-portraits" aria-hidden="true">${icon('archer')}${icon('spear')}${icon('support')}</div></div><div class="camp-actions">${btn(finished?'새 원정 출발 →':started?'원정 이어하기 →':'첫 원정 출발 →',finished?'new-run':'continue','','primary')}${btn('시작 전술 · 해금','camp-loadout')}${btn('내보내기 · 가져오기','backup')}${!finished&&started?btn('새 원정으로 바꾸기','restart-confirm','','danger'):''}</div><div class="info-box"><strong>${finished?'지난 원정':started?'이어갈 원정':'출발 준비'}</strong>${finished?`${r.settlement?.outcome==='complete'?'두 지역 완주':'완료한 목표 정산'} · 증표 ${number(r.settlement?.tokens)}개 획득`:started?`${r.chapter}장 · 방문 ${r.visited.length}/18 · 병사 ${roster().length}명`:'첫 승리 보상 · 신병 모집'}</div>`;
 $('actionBar').innerHTML=btn('플레이 방법','help')+btn('저장 상태','save-info')+btn('기록','result','', 'secondary',!r.history.length);
}
function renderMap(){
 const all=campaign.chapterNodes(),available=new Set(campaign.availableNodes().map(n=>n.id)),complete=new Set(campaign.run.completed),visited=new Set(campaign.run.visited),maxLane=3;
 const lines=all.flatMap(n=>(n.next||[]).map(id=>{const t=all.find(a=>a.id===id);if(!t)return'';const lit=complete.has(n.id)&&visited.has(t.id);return`<line x1="${((n.row===8?1:n.lane)+.5)*100/maxLane}" y1="${(n.row+.5)*100/9}" x2="${((t.row===8?1:t.lane)+.5)*100/maxLane}" y2="${(t.row+.5)*100/9}" stroke="${lit?'#578768':'#b9c9aa'}" stroke-width="${lit?'.8':'.35'}" ${lit?'':'stroke-dasharray="1.3 1.2"'}/>`})).join('');
 $('screen').innerHTML=`<div class="screen-heading"><h3>다음 길 선택</h3><span class="tag">군단 ${roster().length}/${CAP}</span></div>${conditionSummary()}<div class="map-network"><div class="map-scenery" aria-hidden="true">${screenArt()?.backdrop(campaign.run.chapter)||''}</div><svg class="map-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${lines}</svg>${Array.from({length:9},(_,row)=>`<div class="map-row ${row===8?'boss-row':''}"><span class="map-row-label" aria-label="${row+1}번째 길">${row+1}</span>${all.filter(n=>n.row===row).sort((a,b)=>a.lane-b.lane).map(n=>{const current=campaign.run.currentNodeId===n.id,state=current?'current':available.has(n.id)?'available':complete.has(n.id)?'complete':'locked',status=current?'현재':available.has(n.id)?'이동 가능':complete.has(n.id)?'완료':'';return`<button class="map-node ${available.has(n.id)?'next':''} ${complete.has(n.id)?'cleared':''} ${current?'current':''} ${n.type==='boss'?'boss':''}" data-action="node-preview" data-id="${esc(n.id)}" style="grid-column:${n.row===8?2:n.lane+1}" ${current?'aria-current="location"':''} aria-label="${row+1}번째 길 ${esc(nodeName(n))}. ${nodeNames[n.type]||n.type}. ${status||'미도달'}">${current?`<span class="map-current-flag" aria-hidden="true">${screenArt()?.marker('current',18,{state:'current'})||''}</span>`:''}<span class="node-icon" aria-hidden="true">${screenArt()?.marker(n.type,40,{state})||nodeIcon(n.type)||''}</span><span class="node-copy">${esc(nodeNames[n.type]||n.type)}</span>${current||complete.has(n.id)?`<span class="path-marker" aria-hidden="true">${status}</span>`:''}</button>`}).join('')}</div>`).join('')}</div>`;
 $('actionBar').innerHTML=btn('군단 배치 · 기술','formation','','primary')+btn('유물','relics')+btn('기록','result','','secondary',!campaign.run.history.length);
}
function formationMarkup(){
 const selected=roster().find(u=>u.id===selectedUnitId);
 return `<div class="formation-head"><span>후열</span><span>중열</span><span>전열 → 적</span></div><div class="formation-grid" aria-label="후열 중열 전열, 네 자리 배치">${Array.from({length:12},(_,index)=>{const row=Math.floor(index/3),col=index%3,slot=(2-col)*4+row,u=roster().find(u=>u.slot===slot);return`<button class="formation-cell ${u?'occupied':''} ${u&&u.id===selectedUnitId?'selected':''}" data-action="slot" data-slot="${slot}" ${u?`data-unit-id="${u.id}"`:""} aria-description="누르면 선택, 끌면 자리 이동, 길게 누르면 병사 상세" aria-label="${['후열','중열','전열'][col]} ${row+1}번, ${u?label(u)+', 컨디션 '+u.condition+'%':'빈 칸'}" aria-pressed="${!!u&&u.id===selectedUnitId}"><span class="slot-number">${row+1}</span>${u?`<span class="unit-portrait" aria-hidden="true">${icon(u.type,{condition:u.condition,state:u.id===selectedUnitId?'selected':'normal'})}</span><span class="cell-copy"><b>${esc(unitName(u))}</b><small>${esc(TYPES[u.type].name)}</small><small class="unit-condition-value">${metric(u.condition)}%</small>${conditionGauge(u.condition,`${label(u)} 컨디션`,true,{showCaption:false})}</span>`:'<span class="empty-cell" aria-hidden="true">+</span>'}</button>`}).join('')}</div><p class="selection-note" aria-live="polite" ${selected?'':'hidden'}>${selected?`${esc(unitName(selected))} · 옮길 칸 선택`:''}</p>${selected?btn('병사 상세','unit-detail',`data-id="${selected.id}"`):''}`;
}
function relicStrip(){return campaign.run.relics.length?`<div class="relic-strip">${campaign.run.relics.map(r=>`<span class="relic-mini">${relicIcon(r)}<span>${esc(relicName(r.id))}<small>${esc(rarityName(r.rarity))}${inactiveRelic(r)?' · 비활성':''}</small></span>`).join('')}</div>`:'<p class="muted">장착한 유물이 없어요. 승리 보상과 상점에서 찾아보세요.</p>'}
function skillGuideMarkup(ids=Object.keys(skills)){return `<div class="skill-guide-list">${ids.map(id=>`<div class="skill-guide-row"><span class="mini-art" aria-hidden="true">${skillIcon(id)}</span><div><strong>${esc(skillName(id))}</strong><p>${esc(C.SKILLS?.[id]?.description||skills[id].copy)}</p><small>재사용 ${C.SKILLS?.[id]?.cooldown||0}초 · ${id==='focus'?'적을 누르면 즉시 사용':'버튼을 누르면 즉시 사용'}</small></div></div>`).join('')}</div>`}
function loadoutMarkup(){return `<div class="loadout-row"><div><b>지휘 기술</b><div class="loadout-skills">${campaign.run.skills.map(id=>`<span><span class="mini-art" aria-hidden="true">${skillIcon(id)}</span>${esc(skillName(id))}</span>`).join('')}</div></div>${btn('기술 바꾸기','skills')}</div>`}
function soldierInspector(){const u=roster().find(v=>v.id===selectedUnitId)||roster()[0];if(!u)return '';const stats=projectedUnit(u);return `<section class="soldier-inspector" aria-label="병사 살펴보기"><div class="inspector-heading"><span class="inspector-portrait" aria-hidden="true">${icon(u.type,{size:112,condition:u.condition,state:u.id===selectedUnitId?'selected':'normal'})}</span><div><span class="eyebrow">${u.id===selectedUnitId?'선택한 병사':'병사 살펴보기'}</span><h3>${esc(unitName(u))}</h3><p>${esc(TYPES[u.type]?.name||u.type)} · 훈련 ${u.training}/${TRAINING.max}</p></div></div><p class="role-headline">${esc(roleHeadlines[u.type]||roles[u.type]||'')}</p><div class="inspector-stats"><span><small>${metricIcon('hp',16)}최대 체력</small><strong>${metric(stats.maxHp)}</strong></span><span><small>${metricIcon('attack',16)}기본공격 피해</small><strong>${metric(stats.basicDamage)}</strong></span>${stats.heal?`<span><small>${metricIcon('heal',16)}치유량</small><strong>${metric(stats.heal)}</strong></span>`:''}${stats.maxMana>0?`<span><small>${metricIcon('mana',16)}비전 화살</small><strong>${metric(stats.skillDamage)}</strong></span>`:''}<span><small>${metricIcon('condition',16)}컨디션</small><strong>${metric(u.condition)}%</strong></span></div>${conditionGauge(u.condition,`${label(u)} 컨디션`,true,{showCaption:false})}${btn('병사 상세','unit-detail',`data-id="${u.id}" aria-label="${esc(label(u))} 상세 보기"`)}<p class="metric-note">현재 훈련·컨디션·유물 기준. 적 방어와 전투 중 일시 효과 적용 전이에요.</p></section>`}
function enemyBrief(){const node=campaign.currentNode;if(campaign.phase!=='prepare'||!node?.encounter)return '';const counts={};for(const enemy of node.encounter.enemies||[]){const type=typeof enemy==='string'?enemy:enemy.type;counts[type]=(counts[type]||0)+1}return `<section class="enemy-brief" aria-label="이번 전장의 적"><div class="screen-heading"><h3>이번 전장의 적</h3>${btn('상세','enemy-info')}</div><div class="enemy-brief-list">${Object.entries(counts).map(([type,count])=>`<div><span class="enemy-brief-art" aria-hidden="true">${icon(type,{size:36})}</span><span>${esc(TYPES[type]?.name||type)}</span><b>×${count}</b></div>`).join('')}</div><p class="metric-note">${esc(node.encounter.tip||node.description||'적의 편성을 보고 군단을 준비하세요.')}</p></section>`}
function formationWorkspace(){return `<div class="formation-workspace"><div class="formation-main">${loadoutMarkup()}${conditionSummary()}${formationMarkup()}</div><aside class="formation-sidebar desktop-supplement" aria-label="편성 참고">${soldierInspector()}${enemyBrief()}</aside></div>`}
function preparedMarkup(before,after){const bonus=C.CONDITION?.preparedDamageBonus??.1,duration=C.CONDITION?.preparedDuration??10;return `<div class="prepared-preview" data-prepared-before="${before}" data-prepared-after="${after}"><strong>${metricIcon('prepared')}전투 준비 ${before?'준비됨':'없음'} → ${after?'준비됨':'없음'}</strong>${after?`<p>다음 전투 첫 ${duration}초간 공격 피해 +${percent(bonus)}. 다음 전투 한 번만 적용되며 중첩되지 않아요.${before?' 이미 가진 준비 효과를 유지해요.':''}</p>`:''}</div>`}
function renderPrepare(){const node=campaign.currentNode;
 $('screen').innerHTML=`${scene('prepare')}<div class="screen-heading"><h3>출정 준비 · ${roster().length}/${CAP}명</h3>${btn('적 정보','enemy-info','','secondary')}</div>${formationWorkspace()}${campaign.run.prepared?`<p class="prepared-status">${metricIcon('prepared')}전투 준비 적용 · 이번 전투 첫 ${C.CONDITION?.preparedDuration??10}초 공격 피해 +${percent(C.CONDITION?.preparedDamageBonus??.1)} · 중첩 없음</p>`:''}<details class="prep-skill-help rules-detail"><summary>기술 효과 · 사용법</summary><p>회복·수호·사기 고양은 누르면 즉시 사용해요. 집중 사격은 적을 선택하면 즉시 발동해요.</p>${skillGuideMarkup(campaign.run.skills)}</details><details class="rules-detail"><summary>장착 유물 · 전장 안내</summary>${relicStrip()}<p>${esc(node?.encounter?.tip||node?.description||'적의 편성을 보고 군단을 준비하세요.')}</p></details><p class="formation-cost-note">${metricIcon('condition')}승리 후 기본 컨디션 소모 ${number(node?.conditionCost)} · 쓰러지면 추가 ${C.CONDITION?.knockoutLoss??4} 소모</p>`;
 $('actionBar').innerHTML=btn('전투 시작 →','start-battle','','primary')+btn('군단','roster')+btn('기록','result','','secondary',!campaign.run.history.length);
}
// Read-only projections use the same growth/basic-attack methods as battle. No RNG or run mutation.
function projectedUnit(unit,changes={}){const u={...unit,...changes,team:'ally'},options={relics:campaign.run.relics,skills:campaign.run.skills,combatRulesVersion:campaign.run.combatRulesVersion||'v05-combat-1'};if(Game.projectUnit)return Game.projectUnit(u,options);const host={relicEffects:C.getRelicEffects?.(options.relics,options.skills)||{},focusTarget:()=>null};Game.prototype.applyGrowth.call(host,u);u.basicDamage=Game.prototype.basicDamage.call(host,u,{team:'enemy'});u.attackInterval=TYPES[u.type].rate;u.attackRange=TYPES[u.type].range;return u}
const offerUnit=offer=>roster().find(u=>u.id===offer.unitId);
const offerTitle=offer=>offer.kind==='relic'?relicName(offer.relic.id):offer.kind==='train'&&offerUnit(offer)?`${label(offerUnit(offer))} 훈련`:offer.kind==='evolve'&&offerUnit(offer)?`${label(offerUnit(offer))} → ${TYPES[offer.type]?.name||offer.type}`:offer.name;
function offerArt(offer){if(offer.kind==='relic')return relicIcon(relicOutcome(offer));const unit=offerUnit(offer),type=offer.type||unit?.type;return type?icon(type,{condition:offer.kind==='recruit'?100:(unit?.condition??100)}):actionIcon(offer.kind)}
function offerText(offer){const u=offerUnit(offer);if(u&&offer.kind==='train')return `${label(u)}의 훈련 ${u.training} → ${u.training+1}/${TRAINING.max}. 최대 체력·공격${u.type==='support'?'·치유':u.type==='mage'?'·주문력·최대 마나':''} 능력이 강화되고 컨디션은 유지돼요.`;if(u&&offer.kind==='evolve')return `${label(u)} → ${label({...u,type:offer.type})}. ${roles[offer.type]||''}. 같은 병사의 훈련과 컨디션은 유지돼요.`;return offer.description||(offer.kind==='relic'?relicDescription(offer.relic):'')}
function unitChange(offer){const u=offerUnit(offer);if(!u||!['train','evolve'].includes(offer.kind))return null;return{before:projectedUnit(u),after:projectedUnit(u,offer.kind==='train'?{training:u.training+1}:{type:offer.type})}}
function changeRows(change){const rows=[['최대 체력','maxHp',''],['기본공격 피해','basicDamage',''],['공격 간격','attackInterval','초'],['공격 사거리','attackRange','']];if(change.before.heal||change.after.heal)rows.push(['치유량','heal','']);if(change.before.maxMana>0||change.after.maxMana>0)rows.push(['주문력','spellPower',''],['비전 화살 피해','skillDamage',''],['최대 마나','maxMana','']);return rows.map(([name,key,unit])=>({name,key,unit,before:change.before[key]||0,after:change.after[key]||0}))}
function rowPair(r){return paired(r.before,r.after)}
function unitChangeText(change){return changeRows(change).map(r=>{const p=rowPair(r);return `${r.name} ${p.before} → ${p.after}${r.unit} (${p.delta}${p.deltaNumber?r.unit:''})`}).join(' · ')}
function comparisonMarkup(change){return `<div class="stat-comparison">${changeRows(change).map(r=>{const p=rowPair(r),delta=p.deltaNumber;return `<div class="stat-row" data-stat="${r.key}" data-trend="${!delta?'same':(r.key==='attackInterval'?delta<0:delta>0)?'up':'down'}"><span class="stat-label">${r.name}</span><span class="stat-values">${p.before} → ${p.after}${r.unit}</span><span class="stat-delta">${p.delta}${delta?r.unit:''}</span></div>`}).join('')}</div>`}
function conditionStats(units=roster()){const values=units.map(u=>Math.max(0,Math.min(100,u.condition)));return {average:values.length?values.reduce((a,b)=>a+b,0)/values.length:0,minimum:values.length?Math.min(...values):0}}
function conditionGauge(value,labelText,compact=true,options={}){if(globalThis.TinyArmyConditionArt)return globalThis.TinyArmyConditionArt.markup(value,{compact,label:labelText,showLabel:false,...options});const n=Math.max(0,Math.min(100,Number(value)||0)),band=n<25?'red':n<50?'orange':n<75?'gold':'green',color={red:'#b5443e',orange:'#ce702d',gold:'#a7831d',green:'#388552'}[band];return `<span class="condition-track condition-${band}" data-condition-band="${band}" role="meter" aria-label="${esc(labelText)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${n}"><i style="width:${n}%;background:${color}"></i></span>`}
function conditionSummary(units=roster(),full=false){const c=conditionStats(units);return `<div class="condition-summary ${full?'':'is-compact'}"><div class="condition-summary-values"><strong>${metricIcon('condition')}군단 컨디션 평균 ${metric(c.average)}%</strong><span>최저 ${metric(c.minimum)}%</span></div>${full?conditionGauge(c.average,'군단 평균 컨디션',false):conditionGauge(c.average,'군단 평균 컨디션',true,{showCaption:false})}</div><details class="condition-help"><summary>컨디션 효과</summary><p>공격·치유 효율은 70 + 0.3 × 컨디션(%)이에요. 최대 체력에는 영향이 없어요. 색 구간은 표시용이며 추가 페널티가 없어요.</p></details>`}
function restProjection(choice){const option=C.REST_OPTIONS?.find(r=>r.id===choice)||{recover:choice==='recover'?35:10};return roster().map(u=>({...u,condition:Math.min(100,u.condition+option.recover)}))}
function restPreview(choice,details=false){const before=conditionStats(),projected=restProjection(choice),after=conditionStats(projected),average=paired(before.average,after.average),minimum=paired(before.minimum,after.minimum);return `<div class="rest-preview-summary"><div class="rest-metrics"><span><small>${metricIcon('condition',16)}평균 컨디션</small><strong>${average.before} → ${average.after}%</strong><em>${signedMetric(average.deltaNumber,'%p')}</em></span><span><small>최저 컨디션</small><strong>${minimum.before} → ${minimum.after}%</strong><em>${signedMetric(minimum.deltaNumber,'%p')}</em></span></div>${details?`<p class="metric-note">컨디션은 최대 100%. 실제 회복량을 표시해요.</p><details class="rules-detail"><summary>병사별 회복량</summary><div class="stat-comparison">${roster().map((u,i)=>{const p=paired(u.condition,projected[i].condition);return `<div class="stat-row" data-trend="${p.deltaNumber>0?'up':'same'}"><span class="stat-label">${esc(label(u))}</span><span class="stat-values">${p.before} → ${p.after}%</span><span class="stat-delta">${signedMetric(p.deltaNumber,'%p')}</span></div>`}).join('')}</div></details>${preparedMarkup(campaign.run.prepared,campaign.run.prepared||choice==='prepare')}`:''}</div>`}
function postbattleSummary(){const h=campaign.run.history.at(-1);if(!h)return '';const loss=roster().map(u=>{const old=h.contributions?.find(v=>v.id===u.id);return old&&Number.isFinite(old.condition)?Math.max(0,old.condition-u.condition):null}).filter(v=>v!==null);return `<p class="postbattle-summary">${h.win?'승리':'전투 종료'} · ${resultDuration(h.time)} · 생존 ${h.survivors}/${h.unitCount}${loss.length?` · 평균 컨디션 소모 ${metric(loss.reduce((a,b)=>a+b,0)/loss.length)}`:''}</p>`}
function compactRelicEffect(r){const effect=C.relicEffect?.(r),def=relicDef(r.id);if(!effect||!def)return relicDescription(r);const value=effect[def.effect],pct=n=>metric(n*100)+'%';return r.id==='banner'?`군단 최대 체력 +${pct(value)}`:r.id==='seal'?`창병 계열 피해 감소 +${pct(value)}p`:r.id==='spear_tip'?`창병 계열 기본공격 +${pct(value)}`:r.id==='medic'?`지원병 치유량 +${pct(value)}`:r.id==='whistle'?`첫 전투불능 때 평타 가속 +${pct(value)} · ${metric(effect.whistleDuration)}초`:r.id==='drum'?`사기 고양 지속 +${metric(value)}초`:r.id==='keen_eye'?`기본공격 치명타 +${pct(effect.critChance)}p · 배율 +${pct(effect.critDamageBonus)}p`:r.id==='arcane_lens'?`마법사 주문력 +${pct(effect.mageSpellPowerBonus)} · 주문 피해 보너스 +${pct(effect.mageSkillDamageBonus)}`:relicDescription(r)}
function relicEffectPair(offer){const preview=liveRelicAction(offer),existing=preview.existing,result=preview.result,key=relicDef(result.id)?.effect,scale=key==='rallyDuration'?1:100,before=existing?C.relicEffect(existing)[key]*scale:0,after=C.relicEffect(result)[key]*scale;return {existing,result,key,p:paired(before,after),unit:key==='rallyDuration'?'초':key==='damageReduction'?'%p':'%',deltaUnit:key==='rallyDuration'?'초':'%p',name:{maxHp:'군단 최대 체력 증가',damageReduction:'창병 계열 피해 감소',basicDamage:'창병 계열 기본공격 증가',supportHeal:'지원병 치유 증가',attackSpeed:'첫 전투불능 시 평타 가속',rallyDuration:'사기 고양 지속 증가'}[key]||'효과'}}
function relicEffectPairs(offer){const primary=relicEffectPair(offer),def=relicDef(primary.result.id),names={critChance:'기본공격 치명타 확률 증가',critDamageBonus:'치명타 총 배율 추가',mageSpellPowerBonus:'마법사 주문력 증가',mageSkillDamageBonus:'마법사 주문 피해 보너스'};if(names[primary.key])primary.name=names[primary.key];if(primary.key==='critChance')primary.unit='%p';const secondary=def?.secondaryEffect;if(!secondary)return [primary];const before=primary.existing?(C.relicEffect(primary.existing)[secondary]||0)*100:0,after=(C.relicEffect(primary.result)[secondary]||0)*100;return [primary,{...primary,key:secondary,name:names[secondary]||'추가 효과',p:paired(before,after),unit:secondary==='critDamageBonus'?'%p':'%',deltaUnit:'%p'}]}
function relicDeltaText(offer){return relicEffectPairs(offer).map(r=>`${r.name} ${r.p.before} → ${r.p.after}${r.unit} (${r.p.delta}${r.p.deltaNumber?r.deltaUnit:''})`).join(' · ')}
function offerSummary(offer){const change=unitChange(offer);if(change)return changeRows(change).filter(r=>['maxHp','basicDamage','heal','skillDamage','maxMana'].includes(r.key)).map(r=>{const p=rowPair(r);return `${r.name} ${p.before} → ${p.after} (${p.delta})`}).join(' · ');if(offer.kind==='recruit'){const u=projectedUnit({type:offer.type,training:0,condition:100});return `${offer.count}명 합류 · 체력 ${metric(u.maxHp)} · 공격 ${metric(u.basicDamage)}${u.heal?` · 치유 ${metric(u.heal)}`:''}${u.maxMana>0?` · 비전 화살 ${metric(u.skillDamage)} · 마나 ${metric(u.startingMana)}/${metric(u.maxMana)}`:''}`}
 if(offer.kind==='relic')return relicDeltaText(offer);return offerText(offer)}
function offerMeta(offer){if(offer.kind==='relic'){const preview=liveRelicAction(offer),result=offer.purchased?relicOutcome(offer):preview.result;return `${rarityName(result.rarity)}${offer.purchased?' · 구입 완료':preview.action==='merge'?' · 효과 중첩':preview.action==='replace'?' · 등급 교체':preview.requiresReplacement?' · 교체 필요':''}`}return offer.kind==='train'&&offer.purchased?`훈련 적용 완료 · 현재 ${offerUnit(offer)?.training||0}/${TRAINING.max}`:offer.kind==='recruit'?`신병 +${offer.count} · 컨디션 100%`:offer.kind==='evolve'?`훈련 ${offerUnit(offer)?.training||0} 유지 · 컨디션 유지`:`훈련 ${offerUnit(offer)?.training||0} → ${(offerUnit(offer)?.training||0)+1} · 컨디션 유지`}
function relicComparison(offer){if(offer.kind!=='relic')return'';const r=relicEffectPair(offer);return `<div class="relic-comparison stat-comparison">${relicEffectPairs(offer).map(r=>`<div class="stat-row"><span class="stat-label">${esc(r.name)}</span><span class="stat-values">${r.p.before} → ${r.p.after}${r.unit}</span><span class="stat-delta">${r.p.delta}${r.p.deltaNumber?r.deltaUnit:''}</span></div>`).join('')}</div><details class="relic-rules"><summary>정확한 효과 · 중첩 규칙</summary><p>${esc(relicDescription(r.result))}</p><p>같은 유물은 한 슬롯을 사용해요. 비전설은 최대 2중첩이며 두 번째 효과는 25%만 추가돼요. 상위 등급으로 교체하면 1중첩으로 초기화돼요. 전설은 중첩되지 않아요.</p></details>`}
// Reward selection is transient UI state, owned by the exact run/reward objects.
// The monotonically changing token also rejects detached controls after a category switch.
function syncRewardSelection(reward,category){
 if(rewardSelectionOwner?.run!==campaign.run||rewardSelectionOwner?.reward!==reward||rewardSelectionOwner?.category!==category){selectedRewardId=null;selectedReplacementId=null;rewardSelectionKey=`${campaign.run.id}:${reward.id}`;rewardSelectionOwner={run:campaign.run,reward,category,version:++rewardSelectionVersion,offer:null}}
 const offers=reward.offers[category]||[],selected=offers.find(o=>o.id===selectedRewardId);
 if(!selected||selected!==rewardSelectionOwner.offer){selectedRewardId=null;selectedReplacementId=null;rewardSelectionOwner.offer=null}
 if(selectedReplacementId&&!campaign.run.relics.some(r=>r.id===selectedReplacementId))selectedReplacementId=null;
 return offers.find(o=>o.id===selectedRewardId)||null;
}
function currentRewardSelection(data){const o=rewardSelectionOwner,r=campaign.run.pendingReward,category=r?.previewCategory||r?.categories[0];if(modalState||view!=='reward'||campaign.phase!=='reward'||!o||o.run!==campaign.run||o.reward!==r||r.claimed||o.category!==category||String(o.version)!==data.owner)return null;return o}
function offerCardTitle(offer){const u=offerUnit(offer);return u&&offer.kind==='train'?`${unitName(u)} 훈련`:u&&offer.kind==='evolve'?`${unitName(u)} → ${TYPES[offer.type]?.name||offer.type}`:offerTitle(offer)}
function offerKeyEffect(offer){if(offer.kind==='relic')return compactRelicEffect(relicOutcome(offer));if(offer.kind==='recruit')return `${offer.count}명 합류 · 컨디션 100%`;if(offer.kind==='train')return `훈련 ${offerUnit(offer)?.training||0} → ${(offerUnit(offer)?.training||0)+1}`;return roles[offer.type]||offerMeta(offer)}
function offerShortSummary(offer){const change=unitChange(offer);if(change)return changeRows(change).filter(r=>['maxHp','basicDamage','heal','skillDamage'].includes(r.key)&&r.before!==r.after).slice(0,3).map(r=>{const p=rowPair(r);return `${r.name} ${p.before} → ${p.after}`}).join(' · ');return offer.kind==='recruit'?offerSummary(offer):offerKeyEffect(offer)}
function offerCautions(offer){const change=unitChange(offer),notes=change?changeRows(change).filter(r=>r.key==='attackInterval'?r.after>r.before:r.after<r.before).map(r=>{const p=rowPair(r);return `${r.name} ${p.before} → ${p.after}${r.unit}`}):[];if(offer.kind==='relic'){const pairs=relicEffectPairs(offer);for(const r of pairs)if(r.p.deltaNumber<0)notes.push(`${r.name} ${r.p.before} → ${r.p.after}${r.unit}`);const r=pairs[0];if(liveRelicAction(offer).action==='replace'&&(r.existing?.stacks||1)>1)notes.push(`기존 중첩 ${r.existing.stacks} → 1`)}return notes.length?`<p class="reward-change-caution">${notes.map(esc).join(' · ')}</p>`:''}
function offerCard(offer,action='offer-select'){const selected=selectedRewardId===offer.id;return `<button class="offer-card ${selected?'selected':''}" data-action="${action}" data-id="${esc(offer.id)}" data-owner="${rewardSelectionOwner.version}" aria-pressed="${selected}"><span class="offer-art" aria-hidden="true">${offerArt(offer)||''}</span><span class="offer-copy"><strong>${esc(offerCardTitle(offer))}</strong><span class="offer-desc">${esc(offerKeyEffect(offer))}</span>${offer.kind==='relic'?`<span class="tag">${esc(offerMeta(offer))}</span>`:''}</span><span class="offer-arrow" aria-hidden="true">${selected?'✓':''}</span></button>`}
function rewardSelectionMarkup(offer){if(!offer)return '<p class="reward-summary" aria-live="polite">보상 하나 선택</p>';const change=unitChange(offer),owner=rewardSelectionOwner.version;return `<section class="reward-selection-panel" aria-label="선택한 보상"><div class="reward-selection-heading"><strong>${esc(offerTitle(offer))}</strong><span class="reward-selection-actions">${btn('상세','offer-preview',`data-id="${esc(offer.id)}" data-owner="${owner}" aria-label="${esc(offerTitle(offer))} 상세"`)}</span></div><p class="reward-selection-summary" aria-live="polite">${esc(offerShortSummary(offer))}</p>${offerCautions(offer)}<div class="reward-comparison-desktop">${change?comparisonMarkup(change):offer.kind==='relic'?relicComparison(offer):''}</div>${offer.requiresReplacement?`<div class="reward-replacement-list" role="group" aria-label="교체할 유물"><strong>교체할 유물 선택</strong><p class="reward-change-caution">선택한 기존 유물과 그 효과가 사라져요.</p>${campaign.run.relics.map(r=>`<button class="reward-replacement-card" data-action="reward-replace-select" data-id="${esc(r.id)}" data-owner="${owner}" aria-pressed="${selectedReplacementId===r.id}">${relicIcon(r)}<span><strong>${esc(relicName(r.id))}</strong><small>${esc(compactRelicEffect(r))}</small></span></button>`).join('')}</div>`:''}</section>`}
function renderReward(){const reward=campaign.run.pendingReward;if(!reward){$('screen').innerHTML='<p>보상 상태를 불러올 수 없어요. 백업을 확인해 주세요.</p>';$('actionBar').innerHTML=btn('야영지','camp');return}const category=reward.previewCategory||reward.categories[0],selected=syncRewardSelection(reward,category),offers=reward.offers[category]||[];
 $('screen').innerHTML=`${scene('reward')}<div class="screen-heading"><h3>승리 보상</h3><span class="tag">군단 ${roster().length}/${CAP}</span></div>${postbattleSummary()}<div class="category-tabs" role="group" aria-label="보상 갈래">${reward.categories.map(cat=>`<button data-action="reward-category" data-category="${cat}" aria-pressed="${category===cat}"><span class="mini-art" aria-hidden="true">${cat==='troop'?actionIcon('recruit'):globalThis.TinyArmyRelicArt?.icon('relic-marching-banner',{size:32})||''}</span>${cat==='troop'?'병력':'유물'} ${reward.offers[cat].length}</button>`).join('')}</div><div class="offer-grid">${offers.map(o=>offerCard(o)).join('')}</div>${!offers.length?'<p class="empty-state">받을 수 있는 후보가 없어요. 다른 갈래를 확인해 주세요.</p>':''}<div class="reward-selection-region">${rewardSelectionMarkup(selected)}</div>`;
 $('actionBar').innerHTML=btn('받기','reward-claim',`data-owner="${rewardSelectionOwner.version}" data-id="${esc(selected?.id||'')}"`,'primary',!selected||(selected.requiresReplacement&&!selectedReplacementId))+btn('군단 · 유물','roster')+btn('더보기','reward-menu');
}
// Progress only after an explicit successful action. The engine remains the sole
// progression authority; boss/settlement scenes keep their existing transition.
function finishNodeAction(){if(campaign.phase==='nodeComplete'&&campaign.currentNode?.type!=='boss'&&campaign.run.row!==8)mutation('advance');render();$('stageHeading').setAttribute('tabindex','-1');$('stageHeading').focus({preventScroll:true})}
function claimSelectedReward(data){const owner=currentRewardSelection(data),offer=owner?.offer;if(!offer||offer.id!==selectedRewardId||data.id!==offer.id||!owner.reward.offers[owner.category]?.includes(offer)||(offer.requiresReplacement&&!campaign.run.relics.some(r=>r.id===selectedReplacementId)))return;const card=[...$('screen').querySelectorAll('[data-action="offer-select"]')].find(e=>e.dataset.id===offer.id),from=motion()?.capture(card),portrait=motion()?.capture(card?.querySelector('.offer-art'));if(!mutation('claimReward',offer.id,selectedReplacementId))return;selectedRewardId=null;selectedReplacementId=null;rewardSelectionOwner=null;finishNodeAction();const to=$('actionBar').querySelector('[data-action="roster"]')||$('stageHeading');motion()?.rewardClaim({from,to,kind:offer.kind});if(offer.kind==='evolve')motion()?.evolution({target:portrait||from||to,type:offer.type});say('보상을 군단에 더했어요.')}
function restSummary(choice){const def=C.REST_OPTIONS?.find(r=>r.id===choice);return choice==='recover'?`전원 컨디션 +${def?.recover??35} · 최대 100%`:`컨디션 +${def?.recover??10} · 다음 전투 첫 ${def?.duration??10}초 공격 +${percent(def?.bonus??.1)}`}
function armyConditionMarkup(){const stats=conditionStats();return `<section class="army-condition-panel"><div class="screen-heading"><h3>현재 군단 컨디션</h3><span>${roster().length}명</span></div><p class="army-condition-summary">평균 ${metric(stats.average)}% · 최저 ${metric(stats.minimum)}%</p><div class="army-condition-list">${roster().slice().sort((a,b)=>a.condition-b.condition||a.id-b.id).map(u=>`<button class="army-condition-row" data-action="unit-detail" data-id="${u.id}" aria-label="${esc(label(u))}, 컨디션 ${metric(u.condition)}%, 상세 보기"><span class="army-condition-art" aria-hidden="true">${icon(u.type,{size:48,condition:u.condition})}</span><span class="army-condition-copy"><strong>${esc(unitName(u))}</strong><small>${esc(TYPES[u.type]?.name||u.type)}</small>${conditionGauge(u.condition,`${label(u)} 컨디션`,true,{showCaption:false})}</span><b>${metric(u.condition)}%</b></button>`).join('')}</div><p class="metric-note">컨디션이 낮은 병사부터 표시해요. 병사를 누르면 능력치를 볼 수 있어요.</p></section>`}
function renderRest(){$('screen').innerHTML=`${scene('rest')}<div class="screen-heading"><h3>숨을 고르는 시간</h3><span class="tag">하나 선택</span></div><div class="rest-workspace"><div class="rest-main"><div class="option-grid">${['recover','prepare'].map(choice=>`<button class="option-card" data-action="rest-preview" data-choice="${choice}"><span class="rest-card-art" aria-hidden="true">${globalThis.TinyArmyRelicArt.icon(choice==='recover'?'relic-field-medkit':'relic-marching-banner',{size:64})}</span><span class="rest-card-copy"><strong>${choice==='recover'?'군단 휴식':'전투 준비'}</strong><small>${esc(restSummary(choice))}</small></span>${restPreview(choice)}<span class="choice-detail-hint">회복량 상세 →</span></button>`).join('')}</div>${conditionSummary()}${campaign.run.prepared?`<p class="prepared-status">${metricIcon('prepared')}전투 준비 효과 보유 중 · 어느 휴식을 골라도 유지 · 중첩 없음</p>`:''}</div><aside class="rest-sidebar desktop-supplement" aria-label="휴식 전 군단 상태">${armyConditionMarkup()}</aside></div>`;$('actionBar').innerHTML=btn('군단 · 유물','roster')+btn('기록','result','','secondary',!campaign.run.history.length)+btn('야영지','camp')}
// Shop selections are presentation-only; previews and purchases always revalidate live stock.
function syncShopSelection(){const stock=campaign.run.shop,offers=stock?.offers||[];if(shopSelectionOwner?.run!==campaign.run||shopSelectionOwner?.stock!==stock){selectedShopId=offers[0]?.id||null;selectedShopReplacementId=null;shopSelectionOwner={run:campaign.run,stock,node:campaign.currentNode,version:++shopSelectionVersion}}if(!offers.some(o=>o.id===selectedShopId)){selectedShopId=offers[0]?.id||null;selectedShopReplacementId=null}if(selectedShopReplacementId&&!campaign.run.relics.some(r=>r.id===selectedShopReplacementId))selectedShopReplacementId=null;return offers.find(o=>o.id===selectedShopId)||null}
function currentShopSelection(data){const owner=shopSelectionOwner;return !modalState&&view==='shop'&&campaign.phase==='shop'&&owner?.run===campaign.run&&owner.stock===campaign.run.shop&&owner.node===campaign.currentNode&&String(owner.version)===data.owner?owner:null}
function shopPreview(offer,replace){return campaign.previewShop?.(offer.id,replace)||{offerId:offer.id,price:offer.price,purchased:offer.purchased,disabled:true,disabledReason:'상점 정보를 다시 확인해 주세요.',requiresReplacement:false,gold:{before:campaign.run.gold,after:campaign.run.gold-offer.price,delta:-offer.price}}}
function shopReviewKey(offer,preview){return JSON.stringify({preview,offer,roster:roster(),relics:campaign.run.relics,skills:campaign.run.skills})}
function shopWalletMarkup(mobile=false){return `<section class="shop-wallet ${mobile?'shop-wallet-mobile':''}" aria-label="상점 보유 골드"><div class="shop-wallet-amount">${metricIcon('gold',24)}<span><small>보유 골드</small><strong>${number(campaign.run.gold)}<span>G</span></strong></span></div><p>잔액 안에서 여러 상품 구입 · 상품당 한 번</p></section>`}
function purchasedOfferSummary(offer){return offer.kind==='train'?`훈련 적용 완료 · 현재 훈련 ${offerUnit(offer)?.training||0}/${TRAINING.max}`:offer.kind==='recruit'?`신병 ${offer.count}명 합류 완료`:'구매한 유물은 군단에 반영됐어요.'}
function shopPurchaseLabel(preview){return preview.purchased?'구입 완료':preview.disabled?`${metricIcon('lock')}구입 불가`:`${metricIcon('gold')}${number(preview.price)}G 구입`}
function shopProduct(offer){const selected=offer.id===selectedShopId,preview=shopPreview(offer,selected?selectedShopReplacementId:null),owner=shopSelectionOwner.version;return `<article class="shop-product ${selected?'is-selected':''} ${preview.disabled?'is-unavailable':''} ${preview.purchased?'is-purchased':''}" data-shop-offer-id="${esc(offer.id)}" data-selected="${selected}"><button class="shop-product-select" data-action="shop-select" data-id="${esc(offer.id)}" data-owner="${owner}" aria-pressed="${selected}" aria-label="${esc(offerCardTitle(offer))} 비교"><span class="shop-product-art" aria-hidden="true">${offerArt(offer)||''}</span><span class="shop-product-copy"><strong>${esc(offerCardTitle(offer))}</strong><span class="shop-summary">${esc(preview.purchased?purchasedOfferSummary(offer):offerKeyEffect(offer))}</span>${offer.kind==='relic'?`<span class="tag">${esc(rarityName(relicOutcome(offer).rarity))}</span>`:''}</span></button><div class="shop-product-price">${metricIcon('gold')}<strong>${number(preview.price)}G</strong></div>${preview.purchased?'':offerCautions(offer)}<p class="shop-product-status ${preview.disabled?'is-blocked':''}">${preview.purchased?'이 상품은 구입했어요.':preview.disabled?`${metricIcon('lock',16)}${esc(preview.disabledReason)}`:`구입 후 잔액 ${number(preview.gold.after)}G`}</p><div class="shop-product-actions">${btn('상세','shop-preview',`data-id="${esc(offer.id)}" data-owner="${owner}" aria-label="${esc(offerCardTitle(offer))} 상세 보기"`,'secondary shop-detail-button')}${btn(shopPurchaseLabel(preview),'shop-preview',`data-id="${esc(offer.id)}" data-owner="${owner}"`,'primary shop-purchase-button',preview.disabled)}</div></article>`}
function shopReplacementMarkup(offer){const preview=shopPreview(offer,selectedShopReplacementId);if(!preview.requiresReplacement||preview.purchased)return '';return `<div class="shop-replacement-list" role="group" aria-label="교체할 유물"><h4>교체할 유물 선택</h4><p class="reward-change-caution">선택한 기존 유물과 그 효과가 사라져요.</p>${campaign.run.relics.map(r=>`<button class="shop-replacement-card" data-action="shop-replace-select" data-id="${esc(r.id)}" data-owner="${shopSelectionOwner.version}" aria-pressed="${selectedShopReplacementId===r.id}">${relicIcon(r)}<span><strong>${esc(relicName(r.id))}</strong><small>${esc(compactRelicEffect(r))}</small></span></button>`).join('')}</div>`}
function shopSelectionMarkup(offer){if(!offer)return '<p class="empty-state">이 상점에 남은 상품이 없어요.</p>';const preview=shopPreview(offer,selectedShopReplacementId),change=unitChange(offer);return `<section class="shop-selection-panel" aria-label="선택한 상품 비교"><div class="shop-selection-heading"><span class="shop-selection-art" aria-hidden="true">${offerArt(offer)||''}</span><div><span class="eyebrow">선택한 상품</span><h3>${esc(offerCardTitle(offer))}</h3></div></div><p class="shop-selection-summary">${esc(preview.purchased?purchasedOfferSummary(offer):offerShortSummary(offer))}</p><div class="shop-selection-body">${preview.purchased?'<p class="metric-note">이 상품은 한 번 구입했어요. 다른 상품을 선택해 비교하세요.</p>':`${offerCautions(offer)}${change?comparisonMarkup(change):offer.kind==='relic'?relicComparison(offer):`<p class="metric-note">${esc(offerText(offer))}</p>`}${shopReplacementMarkup(offer)}`}</div><div class="shop-gold-after" data-before="${preview.gold.before}" data-after="${preview.gold.after}"><span>${metricIcon('gold')}보유 ${number(preview.gold.before)}G</span><strong>${preview.purchased?'구입 완료':preview.gold.after<0?`${number(-preview.gold.after)}G 부족`:`→ 구입 후 ${number(preview.gold.after)}G`}</strong></div>${preview.disabled?`<p class="shop-product-status is-blocked">${metricIcon('lock',16)}${esc(preview.disabledReason)}</p>`:''}<div class="shop-selection-actions">${btn('상세','shop-preview',`data-id="${esc(offer.id)}" data-owner="${shopSelectionOwner.version}"`,'secondary shop-detail-button')}${btn(shopPurchaseLabel(preview),'shop-preview',`data-id="${esc(offer.id)}" data-owner="${shopSelectionOwner.version}"`,'primary shop-purchase-button',preview.disabled)}</div></section>`}
function renderShop(){const offers=campaign.run.shop?.offers||[],selected=syncShopSelection();$('screen').innerHTML=`${scene('shop')}<div class="screen-heading"><h3>길 위의 보급 상점</h3><span class="tag">남은 상품 ${offers.filter(o=>!o.purchased).length}/${offers.length}</span></div><div class="shop-workspace"><div class="shop-main">${shopWalletMarkup(true)}<div class="shop-product-grid">${offers.map(shopProduct).join('')}</div></div><aside class="shop-sidebar desktop-supplement" aria-label="골드와 상품 비교">${shopWalletMarkup()}${shopSelectionMarkup(selected)}</aside></div>`;$('actionBar').innerHTML=btn('상점 나가기 →','leave-shop','','primary')+btn('군단','roster')+btn('유물','relics')}
function openShopDetail(offer){const preview=shopPreview(offer,offer.id===selectedShopId?selectedShopReplacementId:null);openModal('offer',{id:offer.id,shop:true,run:campaign.run,node:campaign.currentNode,stock:campaign.run.shop,offer,replace:offer.id===selectedShopId?selectedShopReplacementId:null,runId:preview.runId,nodeId:preview.nodeId})}
function eventMetric(kind,title,delta,unit){const trend=delta>0?'up':delta<0?'down':'unchanged';return `<span class="event-metric" data-metric="${kind}" data-trend="${trend}">${metricIcon(kind)}<span>${title} <b>${signedMetric(delta,unit)}</b></span></span>`}
function eventCard(choice){const preview=campaign.previewEvent?.(choice.id);if(!preview)return '';const conditionDelta=paired(preview.condition.average.before,preview.condition.average.after).deltaNumber;return `<article class="event-choice ${preview.disabled?'is-unavailable':''}" data-choice-id="${esc(choice.id)}"><div class="event-choice-heading"><h3>${esc(choice.name)}</h3>${btn('상세 →','event-preview',`data-id="${esc(choice.id)}" aria-label="${esc(choice.name)} 상세 보기"`)}</div><div class="event-choice-metrics">${eventMetric('gold','골드',preview.gold.delta,'G')}${eventMetric('condition','평균 컨디션',conditionDelta,'%p')}${choice.prepared?`<span class="event-metric" data-metric="prepared">${metricIcon('prepared')}<span>다음 전투 첫 ${C.CONDITION?.preparedDuration??10}초 공격 피해 <b>+${percent(C.CONDITION?.preparedDamageBonus??.1)}</b>${preview.prepared.before?' · 준비 유지 · 중첩 없음':' · 중첩 없음'}</span>`:''}</div>${preview.disabled?`<p class="event-unavailable" role="note">${esc(preview.disabledReason||'골드가 부족해 선택할 수 없어요.')} · 상세는 볼 수 있어요.</p>`:''}</article>`}
function eventProjectionRow(kind,title,projection,unit,deltaUnit){const display=paired(projection.before,projection.after),trend=display.deltaNumber>0?'up':display.deltaNumber<0?'down':'same';return `<div class="stat-row event-projection-row" data-stat="${kind}" data-before="${projection.before}" data-after="${projection.after}" data-delta="${projection.delta}" data-trend="${trend}"><span class="stat-label">${metricIcon(kind==='gold'?'gold':'condition')}${title}</span><strong class="stat-values">${display.before}${unit} → ${display.after}${unit}</strong><span class="stat-delta">${signedMetric(display.deltaNumber,deltaUnit)}</span></div>`}
function eventPreviewMarkup(choice,preview){return `<p class="event-choice-description">${esc(choice.description)}</p><div class="event-preview-metrics stat-comparison" aria-label="선택 전과 후">${eventProjectionRow('gold','보유 골드',preview.gold,'G','G')}${eventProjectionRow('average-condition','평균 컨디션',preview.condition.average,'%','%p')}${eventProjectionRow('minimum-condition','최저 컨디션',preview.condition.minimum,'%','%p')}</div>${preview.disabled&&preview.gold.after<0?'<p class="event-cost-note">골드의 음수는 부족분을 나타내요. 이 상태로는 확정할 수 없어요.</p>':''}${choice.costGold?`<p class="event-cost-note">지불 ${number(choice.costGold)}G${choice.rewardGold?` · 획득 ${number(choice.rewardGold)}G`:''}</p>`:''}<p class="metric-note">컨디션은 0–100% 범위에서 적용돼요. 상한·하한을 반영했어요. 소수는 둘째 자리까지 표시하며 변화량은 표시된 전후 수치의 차이예요.</p><details class="rules-detail event-unit-projection"><summary>병사별 컨디션 변화 · ${preview.condition.units.length}명</summary><div class="stat-comparison">${preview.condition.units.map(u=>{const p=paired(u.before,u.after);return `<div class="stat-row" data-unit-id="${u.id}" data-before="${u.before}" data-after="${u.after}" data-delta="${u.delta}" data-trend="${p.deltaNumber>0?'up':p.deltaNumber<0?'down':'same'}"><span class="stat-label">${esc(label(u))}</span><span class="stat-values">${p.before}% → ${p.after}%</span><span class="stat-delta">${signedMetric(p.deltaNumber,'%p')}</span></div>`}).join('')}</div></details>${preparedMarkup(preview.prepared.before,preview.prepared.after)}${preview.disabled?`<p class="risk-box event-unavailable" id="eventUnavailableReason">${esc(preview.disabledReason||'골드가 부족해 선택할 수 없어요.')}</p>`:''}`}
function renderEvent(){const choices=campaign.eventChoices();$('screen').innerHTML=`<div class="screen-heading"><h3>${esc(nodeName(campaign.currentNode)||'길에서 만난 선택')}</h3><span class="event-wallet">${metricIcon('gold')}보유 ${number(campaign.run.gold)}G</span></div><p class="screen-intro">${esc(nodeDescription(campaign.currentNode)||'어떤 선택을 할지 확인하세요.')}</p><div class="event-choice-grid">${choices.map(eventCard).join('')}</div>${campaign.run.prepared?`<p class="prepared-status">${metricIcon('prepared')}전투 준비 효과 보유 중 · 같은 효과는 중첩되지 않아요.</p>`:''}`;$('actionBar').innerHTML=btn('군단 · 유물','roster')+btn('기록','result','','secondary',!campaign.run.history.length)+btn('야영지','camp')}
function renderNodeComplete(){$('screen').innerHTML=`<div class="camp-hero"><span class="eyebrow">ONE STEP FURTHER</span><h2>다음 길을 향해</h2><div class="camp-portraits" aria-hidden="true">${icon('archer')}${icon('spear')}${icon('support')}</div><p>${campaign.run.row===8?'첫 지역을 돌파했어요. 두 번째 지역으로 이어갑니다.':'이곳의 선택을 마쳤어요. 군단을 살피고 다음 길을 골라 보세요.'}</p></div><div class="info-box"><strong>군단 ${roster().length}명 · 보유 ${number(campaign.run.gold)}G</strong>${relicStrip()}</div>`;$('actionBar').innerHTML=btn(campaign.run.row===8?'두 번째 지역으로 →':'다음 길 고르기 →','advance','','primary')+btn('군단','roster')+btn('기록','result','','secondary',!campaign.run.history.length)}
function renderSettlement(){const s=campaign.run.settlement||{},won=s.outcome==='complete';$('screen').innerHTML=`<div class="camp-hero"><span class="eyebrow">${won?'EXPEDITION COMPLETE':'UNTIL THE NEXT JOURNEY'}</span><h2>${won?'두 지역, 원정 완수!':'이번 원정을 마쳤어요'}</h2><div class="camp-portraits" aria-hidden="true">${icon(won?'guardian':'spear')}${icon(won?'sniper':'archer')}${icon('support')}</div><p>${won?'두 번째 장 보스까지 돌파했어요. 이번 공개 원정의 끝입니다.':'완료한 목표의 성과는 군단에 남아요. 다시 준비하고 출발하세요.'}</p></div><div class="settlement"><h3>원정 정산</h3><div class="result-key-stats"><div><b>${number(s.completedBattles)}</b><small>돌파한 전투</small></div><div><b>+${number(s.tokens)}</b><small>획득 증표</small></div><div><b>${campaign.profile.level}</b><small>군단 레벨</small></div></div><p class="metric-note">${won?`완주 보너스 ${number(s.bonus)} 포함. `:''}완료한 목표만 정산돼요. 같은 원정의 정산을 다시 받을 수 없어요.</p>${s.unlocks?.length?`<p style="margin-top:8px">새 해금 · ${s.unlocks.map(id=>esc(id==='vanguard'?'선봉 전술':relicName(id))).join(' · ')}</p>`:''}</div>`;$('actionBar').innerHTML=btn('원정 전체 기록','result','','primary')+btn('새 원정','new-run')+btn('야영지','camp')}
function openModal(viewName,data={}){
 cancelFormationInput();globalThis.TinyArmyConditionTransition?.clear();
 motion()?.clear();
 if(!modalState){focusBeforeModal=document.activeElement;pauseBeforeModal=paused;if(game?.phase==='battle'){paused=true;accumulator=0}}
 modalState={view:viewName,data,page:0,id:++modalSequence};clearNotices();$('modal').hidden=false;$('appShell').inert=true;$('appShell').setAttribute('aria-hidden','true');renderModal(true);if(game)renderBattle();
}
function closeModal(restore=true){if(!modalState)return;cancelFormationInput();const detail=modalState.view==='unit-detail'?modalState.data:null;if(restore&&detail?.returnModal&&detail.run===campaign.run){modalState=detail.returnModal;renderModal(true);focusUnitOrigin(detail);return}modalState=null;clearNotices();$('modal').hidden=true;$('appShell').inert=false;$('appShell').removeAttribute('aria-hidden');if(game?.phase==='battle'){paused=pauseBeforeModal;accumulator=0;renderBattle()}if(restore){const target=focusBeforeModal?.isConnected&&!focusBeforeModal.disabled?focusBeforeModal:($('menuAction')||$('campAction'));target?.focus()}bindFormationInput()}
function enemyMarkup(node=campaign.currentNode){const encounter=node?.encounter,counts={};for(const t of encounter?.enemies||[])counts[typeof t==='string'?t:t.type]=(counts[typeof t==='string'?t:t.type]||0)+1;return `<div class="enemy-list">${Object.entries(counts).map(([type,count])=>`<div class="enemy-entry">${icon(type)}<div><strong>${esc(TYPES[type]?.name||type)} ×${count}</strong><small>${type==='armored'?'타격마다 고정 피해 감소':type==='swarm'?'빠른 접근 · 다수의 낮은 체력 적':type==='brute'||type==='boss'?'붉은 원의 범위 강타':type==='bow'?'후열에서 원거리 공격':'가까운 아군에게 접근'}</small></div></div>`).join('')}</div>${encounter?.tip?`<div class="info-box">${esc(encounter.tip)}</div>`:''}`}
function resultDuration(seconds){const s=Math.max(0,Math.floor(seconds||0));return`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function expeditionContributions(history=campaign.run.history){const total=new Map();for(const record of history)for(const u of record.contributions||[]){const old=total.get(u.id),next={...u};for(const key of ['damage','healing','blocked','damageTaken','kills'])next[key]=(old?.[key]||0)+(u[key]||0);total.set(u.id,next)}return[...total.values()]}
function resultLeaders(units){return `<div class="result-leaders">${[['damage','최다 피해','피해 기록 없음'],['healing','최다 치유','치유 기록 없음'],['blocked','최다 피해 감소','피해 감소 기록 없음']].map(([key,title,empty])=>{const max=Math.max(0,...units.map(u=>u[key]||0)),leaders=max>0?units.filter(u=>Math.abs((u[key]||0)-max)<1e-9):[],u=leaders[0];return`<div class="result-leader"><span class="result-leader-portrait" aria-hidden="true">${u?icon(u.type,{condition:roster().find(v=>v.id===u.id)?.condition??u.condition??100}):''}</span><small>${title}</small><strong>${u?esc(label(u)):empty}</strong><b>${u?number(max):'—'}</b>${leaders.length>1?`<span class="result-tie">외 ${leaders.length-1}명 · 공동 1위</span>`:''}</div>`}).join('')}</div>`}
function resultNode(record){return campaign.run.map.find(n=>n.id===record.nodeId||record.battleId?.endsWith(':'+n.id))}
function resultMarkup(data){const history=campaign.run.history,h=history.at(-1),whole=data.scope==='expedition',units=whole?expeditionContributions():h?.contributions||[],won=history.filter(v=>v.win).length,total=history.reduce((a,v)=>a+(v.time||0),0),fallen=Math.max(0,(h?.unitCount||0)-(h?.survivors||0));
 if(!h)return'<p class="empty-state">아직 완료한 전투가 없어요.</p>';
 return `<div class="result-overview"><p class="result-verdict">${terminal()?campaign.phase==='complete'?'두 번째 장 보스까지 돌파한 군단의 기록이에요.':'완료한 목표는 정산에 남아요. 다음 원정을 준비해 보세요.':h.win?'이 전장의 적을 모두 쓰러뜨렸어요.':'이번 전투가 끝났어요.'}</p><div class="result-scope" role="group" aria-label="기록 범위"><button data-action="result-scope" data-scope="expedition" aria-pressed="${whole}">원정 전체</button><button data-action="result-scope" data-scope="battle" aria-pressed="${!whole}">마지막 전투</button></div><div class="result-key-stats">${whole?`<div><b>${won}</b><small>돌파한 전투</small></div><div><b>${resultDuration(total)}</b><small>총 전투 시간</small></div><div><b>${units.length}명</b><small>함께한 병사</small></div>`:`<div><b>${h.survivors||0}/${h.unitCount||units.length}</b><small>종료 순간 생존</small></div><div><b>${percent(h.hpRatio)}</b><small>종료 순간 체력</small></div><div><b>${resultDuration(h.time)}</b><small>전투 시간</small></div>`}</div><p class="result-scope-note">${whole?'모든 전투 기록을 합산했어요. 진화 전후 활약도 같은 병사로 모았어요.':`종료 순간 쓰러짐 ${fallen}명${h.win?' · 승리 후 전원 복귀':''}. 생존과 체력은 회복 전 기록이에요.`}</p><h3>${whole?'원정 전체':'마지막 전투'} 활약</h3>${resultLeaders(units)}${btn(data.details?'상세 기록 접기':'상세 기록 보기','result-details',`aria-expanded="${!!data.details}"`)}${data.details?`<div class="result-stage-list">${(whole?history:[h]).map((x,i)=>`<div><span>${esc(x.nodeName||nodeName(resultNode(x))||`${i+1}번째 전투`)}</span><b>${x.win?'돌파':x.reason==='timeout'?'시간 초과':'종료'}</b><small>${resultDuration(x.time)} · 생존 ${x.survivors||0}/${x.unitCount||x.contributions?.length||0}</small></div>`).join('')}</div>${!whole?`<p class="metric-note">전투 중 최저 체력 ${percent(h.minHpRatio)} · 지휘 기술 실제 회복 ${number(h.skillHealing??h.rallyHealing)} · 적 강타 ${number(h.enemySlams)}회</p>${h.enemySummary?.length?`<p class="metric-note">${h.enemySummary.map(e=>`${esc(TYPES[e.type]?.name||e.type)}: 격파 ${e.count-e.survivors}/${e.count}${e.blocked?` · 막아 낸 피해 ${number(e.blocked)}`:''}`).join('<br>')}</p>`:''}`:''}<div class="unit-grid">${units.map(u=>`<div class="contribution-card">${icon(u.type,{condition:roster().find(v=>v.id===u.id)?.condition??u.condition??100})}<strong>${esc(label(u))}</strong><small>피해 ${number(u.damage)} · 치유 ${number(u.healing)}</small><small>피해 감소 ${number(u.blocked)}</small></div>`).join('')}</div><p class="metric-note">치유는 실제 회복량, 피해 감소는 방어·보호로 줄인 피해예요.<br>원정 시드 ${campaign.run.seed} · 같은 편성·경로·틱 입력으로 결과를 재현해요.</p>`:''}</div>`;
}
function rosterMarkup(tab='army'){
 const canArrange=['map','prepare'].includes(campaign.phase),run=campaign.run;
 const tabs=`<div class="roster-tabs" role="group" aria-label="군단 정보"><button data-action="roster-tab" data-tab="army" aria-pressed="${tab==='army'}">군단 ${roster().length}/${CAP}</button><button data-action="roster-tab" data-tab="relics" aria-pressed="${tab==='relics'}">유물 ${run.relics.length}/${C.CAPS?.relicSlots||3}</button></div>`;
 if(tab==='relics')return tabs+(run.relics.length?`<div class="roster-list relic-list">${run.relics.map(r=>`<div class="roster-row relic-row"><span class="roster-portrait" aria-hidden="true">${relicIcon(r)}</span><div class="roster-copy"><strong>${esc(relicName(r.id))}</strong><span class="tag">${esc(rarityName(r.rarity))}${inactiveRelic(r)?' · 비활성':''}</span><p>${esc(relicDescription(r))}</p>${inactiveRelic(r)?'<small>사기 고양을 장착하면 효과가 적용돼요.</small>':''}</div></div>`).join('')}</div>`:'<p class="empty-state">아직 장착한 유물이 없어요.</p>')+'<details class="roster-help"><summary>유물 중첩 · 교체 규칙</summary><p>같은 유물은 한 슬롯을 써요. 비전설은 최대 2중첩이고 두 번째 효과는 25%만 더해져요. 상위 등급 교체 시 중첩은 초기화돼요. 같은 전설은 하나만 소유해요.</p></details>';
 return tabs+`${conditionSummary()}<div class="roster-list">${roster().map(u=>{const stats=projectedUnit(u),live=campaign.phase==='battle'?game?.units.find(v=>v.id===u.id):null;return`<div class="roster-row" data-inspect-unit-id="${u.id}"><span class="roster-portrait" aria-hidden="true">${icon(u.type,{condition:u.condition})}</span><div class="roster-copy"><strong>${esc(label(u))}</strong><small>${esc(roles[u.type]||'')} · 훈련 ${u.training}/${TRAINING.max}</small>${live?`<span class="roster-stats">전투 체력 ${metric(live.hp)}/${metric(live.maxHp)}</span>`:''}<small>${['전열','중열','후열'][Math.floor(u.slot/4)]} ${u.slot%4+1}</small></div><div class="roster-condition"><span>컨디션</span><b class="unit-condition-value">${metric(u.condition)}%</b>${conditionGauge(u.condition,`${label(u)} 컨디션`,true,{showCaption:false})}${btn('상세','unit-detail',`data-id="${u.id}" aria-label="${esc(label(u))} 상세 보기"`)}</div></div>`}).join('')}</div><details class="roster-help"><summary>능력치 · 컨디션 안내</summary><p>표시 능력치는 현재 훈련·컨디션·장착 유물 기준이에요. 공격은 적 방어와 전투 중 일시 효과 적용 전 기본공격 피해예요. 전투가 끝나면 체력은 회복하지만 컨디션은 유지돼요.</p></details>${canArrange?'':`<p id="formationLockNote" class="formation-lock-note">${campaign.phase==='reward'?'보상을 받은 뒤 다음 지도나 출정 준비에서 배치를 바꿀 수 있어요.':campaign.phase==='battle'?'전투 중에는 배치를 바꿀 수 없어요. 다음 지도나 출정 준비에서 변경하세요.':'지도나 출정 준비에서 배치를 바꿀 수 있어요.'}</p>`}`;
}
// Pointer sessions never own campaign state; every commit revalidates its captured run.
function cancelFormationInput(){formationInput?.cancel()}
function bindFormationInput(){formationInput?.destroy();formationInput=null;const root=modalState?$('modalText'):$('screen'),run=campaign.run,phase=campaign.phase,modal=modalState,screenView=view;const valid=()=>run===campaign.run&&phase===campaign.phase&&modal===modalState&&screenView===view&&root.isConnected&&!document.hidden;
 formationInput=globalThis.TinyArmyFormationInput?.attach(root,{canInteract:valid,onInspect:id=>{if(valid())openUnitDetail(Number(id))},onMove:(id,slot)=>{id=Number(id);slot=Number(slot);if(!valid()||!['map','prepare'].includes(campaign.phase)||!Number.isInteger(slot)||slot<0||slot>=12||!roster().some(u=>u.id===id))return false;if(!mutation('setSlot',id,slot))return false;selectedUnitId=null;if(modalState?.view==='formation')renderModal();else render();root.querySelector(`[data-action="slot"][data-slot="${slot}"]`)?.focus({preventScroll:true});say('군단 배치를 바꿨어요.');return true}});
}
function focusUnitOrigin(data){const root=modalState?$('modalText'):$('screen'),nodes=[...root.querySelectorAll('[data-action]')],target=nodes.find(n=>n.dataset.action===data.originAction&&(data.originAction==='slot'?Number(n.dataset.unitId)===data.id:Number(n.dataset.id)===data.id));target?.focus({preventScroll:true})}
function openUnitDetail(id){const u=roster().find(u=>u.id===id);if(!u)return;const origin=document.activeElement,returnModal=modalState,originAction=origin?.dataset.action==='unit-detail'&&Number(origin.dataset.id)===id?'unit-detail':returnModal?.view==='formation'||(!returnModal&&view==='prepare')?'slot':'unit-detail';openModal('unit-detail',{id,run:campaign.run,returnModal,originAction});if(!returnModal&&originAction==='slot')focusBeforeModal=[...$('screen').querySelectorAll('[data-unit-id]')].find(e=>Number(e.dataset.unitId)===id)||origin}
function unitManaMarkup(unit){const state=game?.unitSkillState?.(unit.id);if(!state||!(state.maxMana>0))return '';return `<div class="unit-mana"><span>마나 ${metric(state.mana)} / ${metric(state.maxMana)}</span><span class="mana-track" role="meter" aria-label="${esc(label(unit))} 마나" aria-valuemin="0" aria-valuemax="${state.maxMana}" aria-valuenow="${state.mana}"><i style="width:${Math.max(0,Math.min(100,state.mana/state.maxMana*100))}%"></i></span><small>비전 화살 · ${state.remaining>0?`재사용 ${metric(state.remaining)}초`:state.mana<state.cost?'마나 회복 중':state.canCast?'시전 가능':'대상 대기'} · 지휘 기술과 별개</small></div>`}
function unitDetailMarkup(u){const stats=projectedUnit(u),live=campaign.phase==='battle'?game?.units.find(v=>v.id===u.id):null;return `<div class="unit-detail"><div class="unit-detail-heading"><span class="unit-detail-portrait" aria-hidden="true">${icon(u.type,{condition:u.condition})}</span><div><h3>${esc(label(u))}</h3><p>${esc(roleHeadlines[u.type]||roles[u.type]||'')}</p><span class="tag">훈련 ${u.training}/${TRAINING.max}</span></div></div><details class="rules-detail"><summary>병과의 정확한 효과</summary><p class="unit-role-trait">${esc(roleTrait(u.type))}</p></details><div class="condition-summary"><strong>컨디션 · 공격/치유 효율 ${metric(70+.3*u.condition)}%</strong>${conditionGauge(u.condition,`${label(u)} 컨디션`,false)}<small>효율 = 70 + 0.3 × 컨디션(%) · 최대 체력에는 영향 없음</small></div><div class="stat-comparison">${globalThis.TinyArmyStrategyView.statRows(stats,{modern:campaign.run.combatRulesVersion==='v08-combat-1'}).map(r=>`<div class="stat-row" data-stat="${r.key}"><span class="stat-label">${r.name}</span><strong class="stat-values">${r.text}</strong></div>`).join('')}</div>${live?`<p>현재 전투 체력 ${metric(live.hp)} / ${metric(live.maxHp)}</p>${unitManaMarkup(live)}`:''}${stats.maxMana>0?'<p class="metric-note">주문력과 비전 화살 피해에는 컨디션이 이미 반영돼요. 표시는 적 방어 적용 전이며 비전 화살은 치명타가 없어요.</p>':''}${campaign.run.combatRulesVersion==='v08-combat-1'?'<p class="metric-note">치명타 배율 150%는 기본 피해의 1.5배예요. 저격수의 세 번째 강화탄·고유 기술·치유·지휘 기술은 치명타에서 제외돼요. 연사수는 한 번의 공격에서 맞은 모든 적에게 같은 치명타 판정을 적용해요.</p>':''}<p class="metric-note">현재 훈련·컨디션·장착 유물을 반영한 능력치예요. 기본공격 피해는 적 방어와 전투 중 일시 효과 적용 전이에요. 유물의 조건부·일시 효과는 실제 전투 상황에 따라 적용돼요.</p><p class="metric-note">컨디션 색은 0–24 빨강 · 25–49 주황 · 50–74 금색 · 75–100 초록으로 표시해요. 색 경계는 전투 규칙의 기준선이 아니에요.</p>${campaign.run.relics.length?`<details><summary>장착 유물</summary>${relicStrip()}</details>`:'<p class="muted">장착한 유물이 없어요.</p>'}</div>`}
function syncVisualSettings(){const settings=visualSettings();for(const [key,value]of Object.entries({graphicsBackground:settings.decorativeBackground,graphicsGlow:settings.glow,graphicsAnimation:settings.uiAnimation,graphicsReducedMotion:settings.reducedMotion}))document.documentElement.dataset[key]=String(value)}
function graphicsMarkup(){const g=graphics();if(!g)return '<p>그래픽 설정을 불러오지 못했어요.</p>';const pref=g.snapshot(),effective=g.effective(),choice=(key,value,text)=>`<button data-action="graphics-value" data-key="${key}" data-value="${value}" aria-pressed="${pref[key]===value}">${text}</button>`;return`<p class="screen-intro">화면 효과와 선명도만 바꿔요. 전투 규칙·배속·판정은 그대로예요.</p><div class="graphics-presets" role="group" aria-label="그래픽 품질">${[['low','낮음'],['default','기본'],['high','높음']].map(([id,name])=>`<button data-action="graphics-preset" data-id="${id}" aria-pressed="${pref.preset===id}">${name}</button>`).join('')}</div><div class="graphics-settings">${[['renderScale','렌더 해상도',[[.75,'75%'],[1,'100%'],[1.25,'125%']]],['pixelRatioCap','기기 픽셀 배율 상한',[[1,'1×'],[1.5,'1.5×'],[2,'2×']]],['particleAmount','장식 효과량',[[0,'끔'],[.5,'적게'],[1,'많이']]]].map(([key,name,values])=>`<div class="graphics-row"><span>${name}</span><div role="group" aria-label="${name}">${values.map(([value,text])=>choice(key,value,text)).join('')}</div></div>`).join('')}${[['decorativeBackground','배경 장식'],['glow','광채 효과'],['uiAnimation','화면 전환 효과'],['reducedMotion','동작 줄이기']].map(([key,name])=>`<div class="graphics-row"><span>${name}</span><button data-action="graphics-value" data-key="${key}" data-value="${!pref[key]}" aria-pressed="${pref[key]}">${pref[key]?'켜짐':'꺼짐'}</button></div>`).join('')}</div>${effective.systemReducedMotion?'<p class="metric-note">기기의 동작 줄이기 설정에 따라 장식 효과와 화면 전환 효과가 꺼져 있어요.</p>':pref.reducedMotion?'<p class="metric-note">동작 줄이기가 켜져 장식 효과와 화면 전환 효과가 꺼져 있어요.</p>':''}${g.storageError?`<p class="risk-box">${esc(g.storageError)}</p>`:''}<p class="metric-note">강타 범위·체력·집중 대상 표시는 모든 품질에서 유지돼요. 설정은 이 브라우저에만 저장돼요.</p>`}
