 const living=game.alive('ally'),enemies=game.alive('enemy'),armyRatio=Math.max(0,Math.min(1,game.measureHP())),weakest=living.reduce((low,u)=>!low||u.hp/u.maxHp<low.hp/low.maxHp?u:low,null);$('hpStat').textContent=percent(armyRatio);$('unitStat').textContent=`${living.length}/${game.units.length}`;$('enemyStat').textContent=enemies.length;
 if($('armyHealthFill'))$('armyHealthFill').style.width=`${armyRatio*100}%`;
