 if($('lowestHp')){$('lowestHp').textContent=weakest?`최저 체력 비율 · ${label(weakest)} ${percent(weakest.hp/weakest.maxHp)} (${metric(weakest.hp)}/${metric(weakest.maxHp)})`:'생존한 아군 없음';$('lowestHp').dataset.danger=String(!!weakest&&weakest.hp/weakest.maxHp<=.3)}
