 const threats=game.telegraphs.filter(t=>t.team==='enemy'),warning=threats.length>0,lowHp=living.filter(u=>u.hp/u.maxHp<=.3),danger=warning?`범위 강타 ${seconds(Math.min(...threats.map(t=>t.left)))} 후${threats.length>1?` · ${threats.length}곳`:''}`:'',low=lowHp.length?`체력 위험 ${lowHp.length}명`:'';
 $('fieldStatus').textContent=targeting?'적 선택 · 빈 곳을 누르면 취소':paused?['일시정지',danger,low].filter(Boolean).join(' · '):[danger,low].filter(Boolean).join(' · ');$('fieldStatus').hidden=!$('fieldStatus').textContent;$('fieldStatus').classList.toggle('warning',warning);$('fieldStatus').classList.toggle('low-hp',!!lowHp.length);
 $('pauseAction').textContent=paused?'계속':'일시정지';$('pauseAction').disabled=!!targeting;$('speedAction').textContent=`×${speed} 속도`;$('speedAction').setAttribute('aria-label',`현재 ${speed}배속, 누르면 ${speed===3?1:speed+1}배속`);
 const active=[];
 campaign.run.skills.forEach((id,index)=>{const b=$(index?'skillB':'skillA'),state=game.getSkillState(id),waiting=(state?.remaining||0)>0,effect=skillEffectRemaining(id),progress=waiting&&state.cooldown?Math.min(1,state.remaining/state.cooldown):0,status=waiting?`재사용 ${Math.ceil(state.remaining)}초`:id==='heal'&&!state?.canCast?'부상병 없음':id==='focus'?'적 선택':'즉시 사용';
  b.dataset.action='cast-skill';b.dataset.id=id;b.dataset.ready=String(!!state?.canCast);b.innerHTML=`<span class="skill-icon ${waiting?'cooling':''}" style="--cooldown-progress:${progress}" aria-hidden="true">${skillIcon(id)}${waiting?`<span class="skill-timer">${Math.ceil(state.remaining)}</span>`:''}</span><span class="skill-copy"><strong>${esc(skillName(id))}</strong><small class="skill-cooldown">${status}</small></span>`;b.disabled=!state?.canCast||!!targeting||!!modalState||document.hidden||view!=='battle';b.setAttribute('aria-label',`${skillName(id)}, ${status}${effect?`, 효과 ${seconds(effect)} 남음`:''}`);b.setAttribute('title',C.SKILLS?.[id]?.description||skills[id].copy);if(effect)active.push(`<span class="skill-buff" data-skill="${id}">${esc(skillName(id))} ${seconds(effect)}</span>`);
 });
 const whistleUntil=Math.max(0,...living.map(u=>u.whistleUntilTick||0)),whistleLeft=Math.max(0,(whistleUntil-game.tickCount)*STEP);if(whistleLeft)active.push(`<span class="skill-buff" data-skill="whistle">반격 호각 ${seconds(whistleLeft)}</span>`);
